}\n\n    private String safeMessage(Exception e) {\n        String message = e.getMessage();\n        if (message == null) {\n            return e.getClass().getSimpleName();\n        }\n        return message.length() > 1000 ? message.substring(0, 1000) : message;\n    }\n}\n"
